import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"String / Char / Unicode Layering","description":"","frontmatter":{"title":"String / Char / Unicode Layering","type":"adr","date":"2026-09-07T00:00:00.000Z","status":"accepted","status_note":"Accepted — retroactively documented after the implementation already landed on\\nmain. The code described here predates this ADR."},"headers":[],"relativePath":"handl/project/adrs/0093-string-char-unicode-layering.md","filePath":"vendored/handl/project/adrs/0093-string-char-unicode-layering.md"}`),a={name:`handl/project/adrs/0093-string-char-unicode-layering.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0093-string-char-unicode-layering" tabindex="-1">ADR-0093: String / Char / Unicode Layering <a class="header-anchor" href="#adr-0093-string-char-unicode-layering" aria-label="Permalink to “ADR-0093: String / Char / Unicode Layering”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-three-layers-contract-pure-handl-implementation-native-backend" tabindex="-1">1. Three layers: contract, pure-handl implementation, native backend <a class="header-anchor" href="#_1-three-layers-contract-pure-handl-implementation-native-backend" aria-label="Permalink to “1. Three layers: contract, pure-handl implementation, native backend”">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>File / crate</th><th>Role</th></tr></thead><tbody><tr><td><code>str</code> contract</td><td><code>handl-packages/str/str.hnl</code></td><td>45 axioms + laws; no implementation; <code>String</code>/<code>Float</code> are treated as type variables.</td></tr><tr><td><code>char</code> contract</td><td><code>handl-packages/char/char.hnl</code></td><td>18 axioms; semantic names (<code>is_whitespace</code>, <code>is_alpha</code>, …) with no encoding or byte-offset leakage.</td></tr><tr><td><code>str</code> canonical impl</td><td><code>handl-packages/str-handl/str-handl.hnl</code></td><td>Pure handl over <code>char.*</code>; <code>kit-canonical</code> registers it as the module named <code>&quot;str&quot;</code>.</td></tr><tr><td><code>char</code> native backend</td><td><code>crates/plugin-lib-char-native</code></td><td>Rust <code>std::char</code> Unicode scalar-value backend for <code>char.*</code> ops.</td></tr><tr><td><code>unicode</code> contract</td><td><code>handl-packages/unicode/unicode.hnl</code></td><td>Graphemes / normalization / casefold / width (UAX #29/#15/#11).</td></tr><tr><td><code>unicode</code> backend</td><td><code>handl-packages/unicode-c/unicode-c.hnl</code></td><td>Pure-handl module over the host&#39;s ICU4C (<code>libicuuc</code>) via the generic FFI surface.</td></tr></tbody></table><p><code>unicode-c</code> is the <code>unicode</code> analogue of <code>intl-c</code> — a <em>contract + C backend</em> pair rather than a contract + pure-handl + native trio. It splits by need: <code>code_points</code> / <code>from_code_points</code> / <code>is_ascii</code> / <code>code_point_at</code> / <code>decode</code> are pure handl and exact on any host, while <code>graphemes</code> / <code>grapheme_count</code> (<code>ubrk_*</code>, UAX #29), <code>nfc</code> / <code>nfd</code> (<code>unorm2_*</code>, UAX #15), <code>casefold</code> (<code>u_strFoldCase</code>), the XID predicates (<code>u_hasBinaryProperty</code>, UAX #31), and <code>width</code> (<code>u_getIntPropertyValue</code> East Asian Width + <code>u_charType</code>, UAX #11) call ICU4C. <code>available</code> / <code>icu_version</code> report probe results, and the table-dependent ops raise <code>icu-unavailable</code> on a host without ICU.</p><p><strong>Superseded (see &quot;Update&quot; below):</strong> the ICU4X-backed native <code>crates/plugin-lib-unicode-native</code>, the coarse pure-handl <code>handl-packages/unicode-handl</code> fallback, and the lightweight Rust <code>crates/plugin-lib-unicode</code> (<code>UnicodeLibraryPlugin</code>) that the kit <code>LibraryRegistry</code> exposed as the <code>unicode</code> library.</p><h3 id="_2-invariants-that-the-split-preserves" tabindex="-1">2. Invariants that the split preserves <a class="header-anchor" href="#_2-invariants-that-the-split-preserves" aria-label="Permalink to “2. Invariants that the split preserves”">​</a></h3><ul><li><code>str-handl</code> calls only <code>char.*</code> semantic atoms. It never indexes bytes, manipulates UTF-8, or assumes a particular encoding. This lets the same source run over <code>char-native</code>, <code>char-ascii</code>, <code>char-js</code>, or a future <code>char-icu</code> backend.</li><li><code>char</code> names are <em>semantic</em>: <code>is_whitespace</code>, <code>is_alpha</code>, <code>to_upper</code>, etc. The contract deliberately never mentions <code>is_ascii_*</code>, <code>utf8_at</code>, or byte offsets.</li><li>Indices in <code>char</code> and <code>str</code> are character (scalar) indices, not byte offsets.</li><li><code>char.chars</code> and <code>char.from_chars</code> are the bulk conversion atoms. They make string iteration <code>O(n)</code> total instead of <code>O(n^2)</code> through repeated <code>char.at</code>.</li><li><code>unicode-c</code> provides the subset computable from <code>char.*</code> alone exactly, and delegates every table-dependent op to ICU4C. There is deliberately <strong>no coarse fallback</strong>: a code-point-level <code>graphemes</code> or <code>width</code> is silently wrong off ASCII, so on a host without ICU the table-dependent ops fail loudly instead of returning plausible-looking wrong data.</li></ul><h3 id="_3-canonical-registration-and-fallback-ordering" tabindex="-1">3. Canonical registration and fallback ordering <a class="header-anchor" href="#_3-canonical-registration-and-fallback-ordering" aria-label="Permalink to “3. Canonical registration and fallback ordering”">​</a></h3><ul><li><code>kit-canonical</code> resolves the module name <code>&quot;str&quot;</code> to <code>str-handl</code> through its <code>StdlibResolver</code> before the all-FFI <code>str</code> table row in <code>plugin-lib-stdlib</code> (<code>ops::strs</code>) is reached. <code>str.*</code> and <code>from &quot;str&quot; import</code> therefore resolve to the pure-handl implementation in canonical kits.</li><li>Non-canonical kits that do not wire the <code>char</code> resolver still get the FFI <code>str</code> ops through the <code>utils</code> package table, keeping the old behavior as a fallback.</li><li><code>&quot;char&quot;</code> resolves to <code>CharModule</code> (<code>plugin-lib-char-native</code>) directly in <code>kit-canonical</code>.</li><li><code>&quot;unicode_c&quot;</code> resolves to the <code>unicode_c</code> table module (<code>unicode-c.hnl</code>), registered by <code>kit-canonical</code>&#39;s module chain like <code>intl_c</code>. There is no fallback record: every name in the contract is implemented by <code>unicode-c</code>, and the table-dependent ones raise when the host has no ICU.</li><li>The module name is <code>unicode_c</code>, <strong>not</strong> <code>unicode</code> (a deliberate surface change mirroring <code>intl</code>/<code>intl_c</code> — the contract package name is not the runtime module name). <code>unicode_c</code>&#39;s own bare-name imports (<code>result</code>, <code>bytes</code>) and its <code>../generated/icu-uc-c-linux-x86_64/*</code> adapter imports resolve through that same chain.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The <code>str</code>/<code>char</code>/<code>unicode</code> surface in handl has to work across runtimes whose string representations differ (Rust <code>String</code>/UTF-8, JS UTF-16, future backends). <code>str</code> is also the most common standard-library surface, so the implementation must be maintainable and the semantics must not be locked to one FFI backend.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>String algorithms are backend-neutral and portable. Swapping the <code>char</code></li><li>The <code>str</code> contract in <code>str.hnl</code> carries laws and parseable guarantees for the</li><li>Unicode tables come from the host&#39;s ICU4C — the same library <code>intl-c</code></li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0093-string-char-unicode-layering.html"><code>design/0093-string-char-unicode-layering.md</code></a>.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};